22	/* ---- 共用参数 ---- */
23	#define WAKE_THR         0.612f        /* 唤醒阈值 (feature_config.json target_threshold) */
24	#define WAKE_HOP_SAMPLES (MEL_SR / 10) /* 100ms 步长 */
25	#define WAKE_MIN_DIST    12            /* 两次唤醒最小间隔(帧, 1帧=100ms) */
26	#define WAKE_MIC_DEVICE  "/dev/audio/pcm0c"
27	
28	/* ---- 推理缓冲区 ---- */
29	static float buf_conv1[MEL_NFRAMES * MEL_NMELS * 8];      /* 49*40*8 */
30	static float buf_pool1[24 * 20 * 8];
31	static float buf_conv2[24 * 20 * 16];
32	static float buf_pool2[12 * 10 * 16];
33	static float buf_conv3[12 * 10 * 32];
34	static float buf_gap[32];
35	static float buf_d1[16];
36	
37	/* 3x3 same padding, stride 1, +ReLU. w 布局 (kh,kw,in,out), b[out] */
38	static void conv3x3_same_relu(const float *in, int H, int W, int Cin,
39	                              const float *w, const float *b, int Cout,
40	                              float *out) {
41	  for (int o = 0; o < Cout; ++o) {
42	    for (int h = 0; h < H; ++h) {
43	      for (int p = 0; p < W; ++p) {
44	        float acc = b[o];
45	        for (int kh = 0; kh < 3; ++kh) {
46	          int ih = h + kh - 1;
47	          if (ih < 0 || ih >= H) continue;
48	          for (int kw = 0; kw < 3; ++kw) {
49	            int iw = p + kw - 1;
50	            if (iw < 0 || iw >= W) continue;
51	            const float *ip = in + ((ih * W) + iw) * Cin;
52	            for (int c = 0; c < Cin; ++c)
53	              acc += ip[c] * w[(((kh * 3) + kw) * Cin + c) * Cout + o];
54	          }
55	        }
56	        out[((h * W) + p) * Cout + o] = acc > 0 ? acc : 0;
57	      }
58	    }
59	  }
60	}
61	
62	/* 2x2 max pool, stride 2, valid */
63	static void maxpool2(const float *in, int H, int W, int C, float *out,
64	                     int *oH, int *oW) {
65	  *oH = H / 2;
66	  *oW = W / 2;
67	  for (int h = 0; h < *oH; ++h)
68	    for (int w = 0; w < *oW; ++w)
69	      for (int c = 0; c < C; ++c) {
70	        float m = in[((2 * h) * W + (2 * w)) * C + c];
71	        float t;
72	        t = in[((2 * h) * W + (2 * w + 1)) * C + c];
73	        if (t > m) m = t;
74	        t = in[((2 * h + 1) * W + (2 * w)) * C + c];
75	        if (t > m) m = t;
76	        t = in[((2 * h + 1) * W + (2 * w + 1)) * C + c];
77	        if (t > m) m = t;
78	        out[((h * (*oW)) + w) * C + c] = m;
79	      }
80	}
81	
82	/* 全局平均池化 */
83	static void gap(const float *in, int H, int W, int C, float *out) {
84	  for (int c = 0; c < C; ++c) {
85	    float s = 0;
86	    for (int i = 0; i < H * W; ++i) s += in[i * C + c];
87	    out[c] = s / (H * W);
88	  }
89	}
90	
91	/* dense + ReLU. w 布局 (in,out) */
92	static void dense_relu(const float *in, int Din, const float *w,
93	                       const float *b, int Dout, float *out) {
94	  for (int o = 0; o < Dout; ++o) {
95	    float acc = b[o];
96	    for (int i = 0; i < Din; ++i) acc += in[i] * w[i * Dout + o];
97	    out[o] = acc > 0 ? acc : 0;
98	  }
99	}
100	
101	/* dense + softmax */
102	static void dense_softmax(const float *in, int Din, const float *w,
103	                          const float *b, int Dout, float *out) {
104	  float mx = -1e30f;
105	  for (int o = 0; o < Dout; ++o) {
106	    float acc = b[o];
107	    for (int i = 0; i < Din; ++i) acc += in[i] * w[i * Dout + o];
108	    out[o] = acc;
109	    if (acc > mx) mx = acc;
110	  }
111	  float s = 0;
112	  for (int o = 0; o < Dout; ++o) {
113	    out[o] = expf(out[o] - mx);
114	    s += out[o];
115	  }
116	  for (int o = 0; o < Dout; ++o) out[o] /= s;
117	}
118	
119	/* mel: [49*40] float -> prob: [3] */
120	static void predict(const float *mel, float *prob) {
121	  conv3x3_same_relu(mel, MEL_NFRAMES, MEL_NMELS, CONV1_IN, conv1_w, conv1_b,
122	                    CONV1_OUT, buf_conv1);
123	  int H, W;
124	  maxpool2(buf_conv1, MEL_NFRAMES, MEL_NMELS, CONV1_OUT, buf_pool1, &H, &W);
125	  conv3x3_same_relu(buf_pool1, H, W, CONV2_IN, conv2_w, conv2_b, CONV2_OUT,
126	                    buf_conv2);
127	  maxpool2(buf_conv2, H, W, CONV2_OUT, buf_pool2, &H, &W);
128	  conv3x3_same_relu(buf_pool2, H, W, CONV3_IN, conv3_w, conv3_b, CONV3_OUT,
129	                    buf_conv3);
130	  gap(buf_conv3, H, W, CONV3_OUT, buf_gap);
131	  dense_relu(buf_gap, CONV3_OUT, dense1_w, dense1_b, DENSE1_OUT, buf_d1);
132	  dense_softmax(buf_d1, DENSE1_OUT, dense2_w, dense2_b, DENSE2_OUT, prob);
133	}
