135	/* 读 raw PCM 文件 (16k/mono/16bit, 无文件头) -> float[-1,1], 返回样本数 */
136	static int read_pcm(const char *path, float **out_samples) {
137	  FILE *fp = fopen(path, "rb");
138	  if (!fp) {
139	    syslog(LOG_INFO, "无法打开 %s\n", path);
140	    return -1;
141	  }
142	  fseek(fp, 0, SEEK_END);
143	  long bytes = ftell(fp);
144	  fseek(fp, 0, SEEK_SET);
145	  if (bytes <= 0) {
146	    syslog(LOG_INFO, "文件为空: %s\n", path);
147	    fclose(fp);
148	    return -1;
149	  }
150	  size_t n = bytes / 2;            /* 16bit -> 每样本 2 字节 */
151	  int16_t *raw = malloc(n * 2);
152	  size_t got = fread(raw, 2, n, fp);
153	  fclose(fp);
154	  float *s = malloc(got * sizeof(float));
155	  for (size_t i = 0; i < got; ++i) s[i] = raw[i] / 32768.0f;
156	  free(raw);
157	  *out_samples = s;
158	  return (int)got;
159	}
160	
161	/* 模式一: 从 raw PCM 文件离线检测 */
162	static int run_from_file(const char *path) {
163	  float *samples = NULL;
164	  int n = read_pcm(path, &samples);
165	  if (n < MEL_SR) {
166	    syslog(LOG_INFO, "样本太少: %d\n", n);
167	    return 1;
168	  }
169	  syslog(LOG_INFO, "pcm: %s  样本=%d  时长=%.2fs (16k/mono/16bit)\n",
170	         path, n, (double)n / MEL_SR);
171	
172	  mel_init();
173	  const int hop = WAKE_HOP_SAMPLES;
174	  const int nwin = 1 + (n - MEL_SR) / hop;
175	  const int smooth = 5;
176	  const int min_dist = (int)(1.2f * MEL_SR / hop);
177	
178	  float *prob = malloc(nwin * sizeof(float));
179	  static float mel[MEL_NFRAMES * MEL_NMELS];
180	  float p3[3];
181	  for (int i = 0; i < nwin; ++i) {
182	    mel_compute(samples + i * hop, mel);
183	    predict(mel, p3);
184	    prob[i] = p3[0];
185	  }
186	
187	  /* 滑动平均 */
188	  float *sm = malloc(nwin * sizeof(float));
189	  for (int i = 0; i < nwin; ++i) {
190	    float s = 0;
191	    int c = 0;
192	    for (int d = -smooth / 2; d <= smooth / 2; ++d) {
193	      int j = i + d;
194	      if (j >= 0 && j < nwin) {
195	        s += prob[j];
196	        ++c;
197	      }
198	    }
199	    sm[i] = s / c;
200	  }
201	
202	  /* 峰值检测: 先收集, 再打印 */
203	  int *peaks = malloc(nwin * sizeof(int));
204	  int np = 0;
205	  for (int i = 1; i < nwin - 1; ++i) {
206	    if (sm[i] >= WAKE_THR && sm[i] >= sm[i - 1] && sm[i] >= sm[i + 1]) {
207	      if (np == 0 || (i - peaks[np - 1]) >= min_dist) {
208	        peaks[np++] = i;
209	      } else if (sm[i] > sm[peaks[np - 1]]) {
210	        peaks[np - 1] = i;
211	      }
212	    }
213	  }
214	  syslog(LOG_INFO, "\n检测到 %d 个唤醒事件 (阈值 %.2f, 最小间隔 1.2s):\n", np, (double)WAKE_THR);
215	  for (int k = 0; k < np; ++k) {
216	    float t = (float)peaks[k] * hop / MEL_SR;
217	    syslog(LOG_INFO, "  %6.2fs  target_prob=%.3f\n", (double)t, (double)sm[peaks[k]]);
218	  }
219	
220	  free(peaks);
221	  free(prob);
222	  free(sm);
223	  free(samples);
224	  return 0;
225	}
