227	/* 模式二: 从麦克风实时采集检测 (参考 nxrecorder, /dev/audio/pcm0c, 16k/16bit/1ch)。
228	 * duration<=0 表示不限时, 直到 Ctrl-C (SIGINT) 停止。 */
229	static struct mic_capture_s *g_cap = NULL;
230	static void on_sigint(int sig) {
231	  (void)sig;
232	  if (g_cap) g_cap->running = 0;   /* 唤醒 mic_capture_read 退出 */
233	}
234	
235	static int run_from_mic(const char *device, int duration) {
236	  struct mic_capture_s cap;
237	  int ret = mic_capture_start(&cap, device, MEL_SR, 1, 16);
238	  if (ret != 0) {
239	    syslog(LOG_INFO, "mic_capture_start 失败: %d\n", ret);
240	    return 1;
241	  }
242	  g_cap = &cap;
243	  signal(SIGINT, on_sigint);
244	  if (duration > 0)
245	    syslog(LOG_INFO, "录音中 %ds, 唤醒阈值 %.2f\n", duration, (double)WAKE_THR);
246	  else
247	    syslog(LOG_INFO, "录音中 (不限时, Ctrl-C 停止), 唤醒阈值 %.2f\n", (double)WAKE_THR);
248	
249	  mel_init();
250	  static float window[MEL_SR];
251	  static int16_t hopbuf[WAKE_HOP_SAMPLES];
252	  static float mel[MEL_NFRAMES * MEL_NMELS];
253	  float p3[3];
254	  memset(window, 0, sizeof(window));
255	
256	  int nframes = (duration > 0) ? (duration * 1000 / 100) : -1;  /* <=0 表示不限时 */
257	  int last_wake = -WAKE_MIN_DIST;
258	  int wakes = 0;
259	  int f;
260	
261	  for (f = 0; nframes < 0 || f < nframes; ++f) {
262	    if (mic_capture_read(&cap, hopbuf, WAKE_HOP_SAMPLES) != 0)
263	      break;   /* Ctrl-C 或停止 */
264	    /* 滑动窗口左移 hop, 末尾追加新数据 */
265	    memmove(window, window + WAKE_HOP_SAMPLES,
266	            (MEL_SR - WAKE_HOP_SAMPLES) * sizeof(float));
267	    for (int i = 0; i < WAKE_HOP_SAMPLES; ++i)
268	      window[MEL_SR - WAKE_HOP_SAMPLES + i] = hopbuf[i] / 32768.0f;
269	
270	    mel_compute(window, mel);
271	    predict(mel, p3);
272	    float prob = p3[0];
273	    float t = (float)f * 0.1f;
274	    if (prob > WAKE_THR && (f - last_wake) >= WAKE_MIN_DIST) {
275	      syslog(LOG_INFO, "[%6.2fs] *** 唤醒 *** target_prob=%.3f\n",
276	             (double)t, (double)prob);
277	      last_wake = f;
278	      ++wakes;
279	    } else {
280	      syslog(LOG_INFO, "[%6.2fs] prob=%.3f\n", (double)t, (double)prob);
281	    }
282	  }
283	
284	  g_cap = NULL;
285	  mic_capture_stop(&cap);
286	  syslog(LOG_INFO, "结束, 共 %d 次唤醒\n", wakes);
287	  return 0;
288	}
