290	/* 判断字符串是否为纯数字 */
291	static int is_number(const char *s) {
292	  if (s == NULL || *s == '\0') return 0;
293	  for (const char *p = s; *p; ++p)
294	    if (*p < '0' || *p > '9') return 0;
295	  return 1;
296	}
