298	int main(int argc, char *argv[]) {
299	  if (argc >= 2 && argv[1][0] != '\0') {
300	    if (is_number(argv[1])) {
301	      /* 数字: 麦克风限时 N 秒 */
302	      return run_from_mic(WAKE_MIC_DEVICE, atoi(argv[1]));
303	    }
304	    /* 非数字: 文件路径 */
305	    return run_from_file(argv[1]);
306	  }
307	  /* 无参数: 麦克风不限时 */
308	  return run_from_mic(WAKE_MIC_DEVICE, 0);
309	}
