1	/* log-mel 前端实现 (纯 C), 对齐 features.py。 */
2	#include <math.h>
3	#include <string.h>
4	#include "mel_features.h"
5	
6	#define PI 3.14159265358979323846f
7	
8	static float g_window[MEL_FRAME_LEN];
9	static float g_filterbank[MEL_NMELS][MEL_NFFT / 2 + 1];
10	static int g_inited = 0;
11	
12	static float hz_to_mel(float f) { return 2595.0f * log10f(1.0f + f / 700.0f); }
13	static float mel_to_hz(float m) { return 700.0f * (powf(10.0f, m / 2595.0f) - 1.0f); }
14	
15	void mel_init(void) {
16	  if (g_inited) return;
17	  /* hamming: 0.54 - 0.46*cos(2*pi*n/(N-1)) */
18	  for (int n = 0; n < MEL_FRAME_LEN; ++n)
19	    g_window[n] = 0.54f - 0.46f * cosf(2.0f * PI * n / (MEL_FRAME_LEN - 1));
20	
21	  /* mel 三角滤波器组 (HTK) */
22	  const float mmin = hz_to_mel(0.0f);
23	  const float mmax = hz_to_mel(8000.0f);
24	  int bin[MEL_NMELS + 2];
25	  for (int i = 0; i < MEL_NMELS + 2; ++i) {
26	    float m = mmin + (mmax - mmin) * i / (MEL_NMELS + 1);
27	    float hz = mel_to_hz(m);
28	    int b = (int)floorf((MEL_NFFT + 1) * hz / MEL_SR);
29	    if (b < 0) b = 0;
30	    if (b > MEL_NFFT / 2) b = MEL_NFFT / 2;
31	    bin[i] = b;
32	  }
33	  for (int m = 0; m < MEL_NMELS; ++m) {
34	    int left = bin[m], center = bin[m + 1], right = bin[m + 2];
35	    for (int k = 0; k < MEL_NFFT / 2 + 1; ++k) g_filterbank[m][k] = 0.0f;
36	    if (center > left)
37	      for (int k = left; k < center; ++k)
38	        g_filterbank[m][k] = (float)(k - left) / (center - left);
39	    if (right > center)
40	      for (int k = center; k < right; ++k)
41	        g_filterbank[m][k] = (float)(right - k) / (right - center);
42	  }
43	  g_inited = 1;
44	}
45	
46	/* 512 点 radix-2 迭代 FFT (in-place) */
47	static void fft512(float *re, float *im) {
48	  const int N = MEL_NFFT;
49	  int j = 0;
50	  for (int i = 1; i < N; ++i) {
51	    int bit = N >> 1;
52	    for (; j & bit; bit >>= 1) j ^= bit;
53	    j ^= bit;
54	    if (i < j) {
55	      float tr = re[i]; re[i] = re[j]; re[j] = tr;
56	      float ti = im[i]; im[i] = im[j]; im[j] = ti;
57	    }
58	  }
59	  for (int len = 2; len <= N; len <<= 1) {
60	    float ang = -2.0f * PI / len;
61	    float wr = cosf(ang), wi = sinf(ang);
62	    for (int i = 0; i < N; i += len) {
63	      float cr = 1.0f, ci = 0.0f;
64	      for (int k = 0; k < len / 2; ++k) {
65	        float ur = re[i + k], ui = im[i + k];
66	        float vr = re[i + k + len / 2] * cr - im[i + k + len / 2] * ci;
67	        float vi = re[i + k + len / 2] * ci + im[i + k + len / 2] * cr;
68	        re[i + k] = ur + vr; im[i + k] = ui + vi;
69	        re[i + k + len / 2] = ur - vr; im[i + k + len / 2] = ui - vi;
70	        float ncr = cr * wr - ci * wi;
71	        ci = cr * wi + ci * wr;
72	        cr = ncr;
73	      }
