#include <stdio.h>
#include <stdlib.h>
#include "mic_capture.h"

static FILE *g_fp = NULL;

int mic_capture_start(struct mic_capture_s *c, const char *device,
                      int samplerate, int channels, int bps) {
  (void)samplerate; (void)channels; (void)bps;
  const char *path = getenv("WAKE_PCM_FILE");
  if (!path || !*path) path = device;
  g_fp = fopen(path, "rb");
  if (!g_fp) return -1;
  c->running = 1;
  return 0;
}

int mic_capture_read(struct mic_capture_s *c, int16_t *out, int nsamples) {
  (void)c;
  if (!g_fp) return -1;
  if (fread(out, 2, nsamples, g_fp) != (size_t)nsamples) return -1; /* EOF */
  return 0;
}

void mic_capture_stop(struct mic_capture_s *c) {
  (void)c;
  if (g_fp) fclose(g_fp);
  g_fp = NULL;
}

