24	 * 单窗判决误报 38~68 次/h; 0.90 + 连续4窗(400ms 持续) 误报 0,
25	 * 唤醒率 92% / 92% / 87% (0/-6/-12dB)。重训模型后需重新调优。 */
26	#define WAKE_THR         0.900f        /* 唤醒阈值 */
27	#define WAKE_CONSEC      4             /* 连续 N 窗超阈才判唤醒 (1帧=100ms) */
28	#define WAKE_HOP_SAMPLES (MEL_SR / 10) /* 100ms 步长 */
