41	/* 3x3 same padding, stride 1, +ReLU. w 布局 (kh,kw,in,out), b[out] */
42	static void conv3x3_same_relu(const float *in, int H, int W, int Cin,
43	                              const float *w, const float *b, int Cout,
44	                              float *out) {
45	  for (int o = 0; o < Cout; ++o) {
46	    for (int h = 0; h < H; ++h) {
47	      for (int p = 0; p < W; ++p) {
48	        float acc = b[o];
49	        for (int kh = 0; kh < 3; ++kh) {
50	          int ih = h + kh - 1;
51	          if (ih < 0 || ih >= H) continue;
52	          for (int kw = 0; kw < 3; ++kw) {
53	            int iw = p + kw - 1;
54	            if (iw < 0 || iw >= W) continue;
55	            const float *ip = in + ((ih * W) + iw) * Cin;
56	            for (int c = 0; c < Cin; ++c)
57	              acc += ip[c] * w[(((kh * 3) + kw) * Cin + c) * Cout + o];
58	          }
59	        }
60	        out[((h * W) + p) * Cout + o] = acc > 0 ? acc : 0;
61	      }
62	    }
63	  }
64	}
65	
66	/* 2x2 max pool, stride 2, valid */
67	static void maxpool2(const float *in, int H, int W, int C, float *out,
68	                     int *oH, int *oW) {
69	  *oH = H / 2;
70	  *oW = W / 2;
71	  for (int h = 0; h < *oH; ++h)
72	    for (int w = 0; w < *oW; ++w)
73	      for (int c = 0; c < C; ++c) {
74	        float m = in[((2 * h) * W + (2 * w)) * C + c];
75	        float t;
76	        t = in[((2 * h) * W + (2 * w + 1)) * C + c];
77	        if (t > m) m = t;
78	        t = in[((2 * h + 1) * W + (2 * w)) * C + c];
79	        if (t > m) m = t;
80	        t = in[((2 * h + 1) * W + (2 * w + 1)) * C + c];
81	        if (t > m) m = t;
82	        out[((h * (*oW)) + w) * C + c] = m;
83	      }
84	}
