86	/* 全局平均池化 */
87	static void gap(const float *in, int H, int W, int C, float *out) {
88	  for (int c = 0; c < C; ++c) {
89	    float s = 0;
90	    for (int i = 0; i < H * W; ++i) s += in[i * C + c];
91	    out[c] = s / (H * W);
92	  }
93	}
