95	/* dense + ReLU. w 布局 (in,out) */
96	static void dense_relu(const float *in, int Din, const float *w,
97	                       const float *b, int Dout, float *out) {
98	  for (int o = 0; o < Dout; ++o) {
99	    float acc = b[o];
100	    for (int i = 0; i < Din; ++i) acc += in[i] * w[i * Dout + o];
101	    out[o] = acc > 0 ? acc : 0;
102	  }
103	}
104	
105	/* dense + softmax */
106	static void dense_softmax(const float *in, int Din, const float *w,
107	                          const float *b, int Dout, float *out) {
108	  float mx = -1e30f;
109	  for (int o = 0; o < Dout; ++o) {
110	    float acc = b[o];
111	    for (int i = 0; i < Din; ++i) acc += in[i] * w[i * Dout + o];
112	    out[o] = acc;
113	    if (acc > mx) mx = acc;
114	  }
115	  float s = 0;
116	  for (int o = 0; o < Dout; ++o) {
117	    out[o] = expf(out[o] - mx);
118	    s += out[o];
119	  }
120	  for (int o = 0; o < Dout; ++o) out[o] /= s;
121	}
