123	/* mel: [49*40] float -> prob: [3] */
124	static void predict(const float *mel, float *prob) {
125	  conv3x3_same_relu(mel, MEL_NFRAMES, MEL_NMELS, CONV1_IN, conv1_w, conv1_b,
126	                    CONV1_OUT, buf_conv1);
127	  int H, W;
128	  maxpool2(buf_conv1, MEL_NFRAMES, MEL_NMELS, CONV1_OUT, buf_pool1, &H, &W);
129	  conv3x3_same_relu(buf_pool1, H, W, CONV2_IN, conv2_w, conv2_b, CONV2_OUT,
130	                    buf_conv2);
131	  maxpool2(buf_conv2, H, W, CONV2_OUT, buf_pool2, &H, &W);
132	  conv3x3_same_relu(buf_pool2, H, W, CONV3_IN, conv3_w, conv3_b, CONV3_OUT,
133	                    buf_conv3);
134	  gap(buf_conv3, H, W, CONV3_OUT, buf_gap);
135	  dense_relu(buf_gap, CONV3_OUT, dense1_w, dense1_b, DENSE1_OUT, buf_d1);
136	  dense_softmax(buf_d1, DENSE1_OUT, dense2_w, dense2_b, DENSE2_OUT, prob);
137	}
