139	/* 读 raw PCM 文件 (16k/mono/16bit, 无文件头) -> float[-1,1], 返回样本数 */
140	static int read_pcm(const char *path, float **out_samples) {
141	  FILE *fp = fopen(path, "rb");
142	  if (!fp) {
143	    syslog(LOG_INFO, "无法打开 %s\n", path);
144	    return -1;
145	  }
146	  fseek(fp, 0, SEEK_END);
147	  long bytes = ftell(fp);
148	  fseek(fp, 0, SEEK_SET);
149	  if (bytes <= 0) {
150	    syslog(LOG_INFO, "文件为空: %s\n", path);
151	    fclose(fp);
152	    return -1;
153	  }
154	  size_t n = bytes / 2;            /* 16bit -> 每样本 2 字节 */
155	  int16_t *raw = malloc(n * 2);
156	  size_t got = fread(raw, 2, n, fp);
157	  fclose(fp);
158	  float *s = malloc(got * sizeof(float));
159	  for (size_t i = 0; i < got; ++i) s[i] = raw[i] / 32768.0f;
160	  free(raw);
161	  *out_samples = s;
162	  return (int)got;
163	}
