165	/* 模式一: 从 raw PCM 文件离线检测 */
166	static int run_from_file(const char *path) {
167	  float *samples = NULL;
168	  int n = read_pcm(path, &samples);
169	  if (n < MEL_SR) {
170	    syslog(LOG_INFO, "样本太少: %d\n", n);
171	    return 1;
172	  }
173	  syslog(LOG_INFO, "pcm: %s  样本=%d  时长=%.2fs (16k/mono/16bit)\n",
174	         path, n, (double)n / MEL_SR);
175	
176	  mel_init();
177	  const int hop = WAKE_HOP_SAMPLES;
178	  const int nwin = 1 + (n - MEL_SR) / hop;
179	  const int smooth = 5;
180	  const int min_dist = (int)(1.2f * MEL_SR / hop);
181	
182	  float *prob = malloc(nwin * sizeof(float));
183	  static float mel[MEL_NFRAMES * MEL_NMELS];
184	  float p3[3];
185	  for (int i = 0; i < nwin; ++i) {
186	    mel_compute(samples + i * hop, mel);
187	    predict(mel, p3);
188	    prob[i] = p3[0];
189	  }
190	
191	  /* 滑动平均 */
192	  float *sm = malloc(nwin * sizeof(float));
193	  for (int i = 0; i < nwin; ++i) {
194	    float s = 0;
195	    int c = 0;
196	    for (int d = -smooth / 2; d <= smooth / 2; ++d) {
197	      int j = i + d;
198	      if (j >= 0 && j < nwin) {
199	        s += prob[j];
200	        ++c;
201	      }
202	    }
203	    sm[i] = s / c;
204	  }
205	
206	  /* 峰值检测: 先收集, 再打印 */
207	  int *peaks = malloc(nwin * sizeof(int));
208	  int np = 0;
209	  for (int i = 1; i < nwin - 1; ++i) {
210	    if (sm[i] >= WAKE_THR && sm[i] >= sm[i - 1] && sm[i] >= sm[i + 1]) {
211	      if (np == 0 || (i - peaks[np - 1]) >= min_dist) {
212	        peaks[np++] = i;
213	      } else if (sm[i] > sm[peaks[np - 1]]) {
214	        peaks[np - 1] = i;
215	      }
216	    }
217	  }
218	  syslog(LOG_INFO, "\n检测到 %d 个唤醒事件 (阈值 %.2f, 最小间隔 1.2s):\n", np, (double)WAKE_THR);
219	  for (int k = 0; k < np; ++k) {
220	    float t = (float)peaks[k] * hop / MEL_SR;
221	    syslog(LOG_INFO, "  %6.2fs  target_prob=%.3f\n", (double)t, (double)sm[peaks[k]]);
222	  }
223	
224	  free(peaks);
225	  free(prob);
226	  free(sm);
227	  free(samples);
228	  return 0;
229	}
