231	/* 模式二: 从麦克风实时采集检测 (参考 nxrecorder, /dev/audio/pcm0c, 16k/16bit/1ch)。
232	 * duration<=0 表示不限时, 直到 Ctrl-C (SIGINT) 停止。 */
233	static struct mic_capture_s *g_cap = NULL;
234	static void on_sigint(int sig) {
235	  (void)sig;
236	  if (g_cap) g_cap->running = 0;   /* 唤醒 mic_capture_read 退出 */
237	}
238	
239	static int run_from_mic(const char *device, int duration) {
240	  struct mic_capture_s cap;
241	  int ret = mic_capture_start(&cap, device, MEL_SR, 1, 16);
242	  if (ret != 0) {
243	    syslog(LOG_INFO, "mic_capture_start 失败: %d\n", ret);
244	    return 1;
245	  }
246	  g_cap = &cap;
247	  signal(SIGINT, on_sigint);
248	  if (duration > 0)
249	    syslog(LOG_INFO, "录音中 %ds, 唤醒条件: 连续%d窗 prob>%.2f\n",
250	           duration, WAKE_CONSEC, (double)WAKE_THR);
251	  else
252	    syslog(LOG_INFO, "录音中 (不限时, Ctrl-C 停止), 唤醒条件: 连续%d窗 prob>%.2f\n",
253	           WAKE_CONSEC, (double)WAKE_THR);
254	
255	  mel_init();
256	  static float window[MEL_SR];
257	  static int16_t hopbuf[WAKE_HOP_SAMPLES];
258	  static float mel[MEL_NFRAMES * MEL_NMELS];
259	  float p3[3];
260	  memset(window, 0, sizeof(window));
261	
262	  int nframes = (duration > 0) ? (duration * 1000 / 100) : -1;  /* <=0 表示不限时 */
263	  int last_wake = -WAKE_MIN_DIST;
264	  int consec = 0;   /* 当前连续超阈窗数 */
265	  int wakes = 0;
266	  int f;
267	
268	  for (f = 0; nframes < 0 || f < nframes; ++f) {
269	    if (mic_capture_read(&cap, hopbuf, WAKE_HOP_SAMPLES) != 0)
270	      break;   /* Ctrl-C 或停止 */
271	    /* 滑动窗口左移 hop, 末尾追加新数据 */
272	    memmove(window, window + WAKE_HOP_SAMPLES,
273	            (MEL_SR - WAKE_HOP_SAMPLES) * sizeof(float));
274	    for (int i = 0; i < WAKE_HOP_SAMPLES; ++i)
275	      window[MEL_SR - WAKE_HOP_SAMPLES + i] = hopbuf[i] / 32768.0f;
276	
277	    mel_compute(window, mel);
278	    predict(mel, p3);
279	    float prob = p3[0];
280	    float t = (float)f * 0.1f;
281	    /* 连续 WAKE_CONSEC 窗超阈才判唤醒: 误报多为孤立单窗尖峰,
282	     * 真唤醒词会连续 10+ 窗超阈。 */
283	    if (prob > WAKE_THR) ++consec; else consec = 0;
284	    if (consec >= WAKE_CONSEC && (f - last_wake) >= WAKE_MIN_DIST) {
285	      syslog(LOG_INFO, "[%6.2fs] *** 唤醒 *** stone111 target_prob=%.3f\n",
286	             (double)t, (double)prob);
287	      last_wake = f;
288	      consec = 0;
289	      ++wakes;
290	    } else {
291	      syslog(LOG_INFO, "[%6.2fs] prob=%.3f\n", (double)t, (double)prob);
292	    }
293	  }
294	
295	  g_cap = NULL;
296	  mic_capture_stop(&cap);
297	  syslog(LOG_INFO, "结束, 共 %d 次唤醒\n", wakes);
298	  return 0;
299	}
