301	/* 判断字符串是否为纯数字 */
302	static int is_number(const char *s) {
303	  if (s == NULL || *s == '\0') return 0;
304	  for (const char *p = s; *p; ++p)
305	    if (*p < '0' || *p > '9') return 0;
306	  return 1;
307	}
