310	  if (argc >= 2 && argv[1][0] != '\0') {
311	    if (is_number(argv[1])) {
312	      /* 数字: 麦克风限时 N 秒 */
313	      return run_from_mic(WAKE_MIC_DEVICE, atoi(argv[1]));
314	    }
315	    /* 非数字: 文件路径 */
